def linear_search(values, target):
    for index in range(len(values)):
        if values[index] == target:
            return index
    return -1

position = linear_search([14, 8, 21, 5], 21)
print(position)  # 2

def binary_search(values, target):
    low = 0
    high = len(values) - 1

    while low <= high:
        mid = (low + high) // 2
        if values[mid] == target:
            return mid
        if values[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return -1

print(binary_search([4, 9, 13, 18, 27, 31], 18))  # 3

def bubble_sort(values):
    for pass_number in range(len(values) - 1):
        swapped = False
        last_pair = len(values) - 1 - pass_number

        for index in range(last_pair):
            if values[index] > values[index + 1]:
                values[index], values[index + 1] = values[index + 1], values[index]
                swapped = True

        if not swapped:
            break

    return values

def insertion_sort(values):
    for index in range(1, len(values)):
        key = values[index]
        position = index - 1

        while position >= 0 and values[position] > key:
            values[position + 1] = values[position]
            position -= 1

        values[position + 1] = key

    return values

class Stack:
    def __init__(self):
        self._items = []

    def is_empty(self):
        return len(self._items) == 0

    def push(self, item):
        self._items.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError("cannot pop an empty stack")
        return self._items.pop()

    def peek(self):
        if self.is_empty():
            raise IndexError("cannot peek at an empty stack")
        return self._items[-1]

class CircularQueue:
    def __init__(self, capacity):
        self._items = [None] * capacity
        self._front = 0
        self._size = 0

    def enqueue(self, item):
        if self._size == len(self._items):
            raise OverflowError("queue is full")
        rear = (self._front + self._size) % len(self._items)
        self._items[rear] = item
        self._size += 1

    def dequeue(self):
        if self._size == 0:
            raise IndexError("queue is empty")
        item = self._items[self._front]
        self._items[self._front] = None
        self._front = (self._front + 1) % len(self._items)
        self._size -= 1
        return item

